import React from 'react';
import Icon from '../AppIcon';

const ErrorState = ({
  title = 'Something went wrong',
  message,
  onRetry,
  retryLabel = 'Try again',
  fullScreen = true,
}) => (
  <div
    className={`flex items-center justify-center ${fullScreen ? 'min-h-[50vh]' : 'py-12'}`}
    role="alert"
  >
    <div className="text-center max-w-md mx-auto px-4">
      <Icon name="AlertTriangle" size={48} className="text-warning mx-auto mb-4" aria-hidden="true" />
      <h3 className="text-xl font-semibold text-text-primary mb-2">{title}</h3>
      {message && <p className="text-text-secondary mb-4">{message}</p>}
      {onRetry && (
        <button
          type="button"
          onClick={onRetry}
          className="bg-primary text-white px-4 py-2 rounded-lg font-medium hover:bg-primary-700 transition-colors focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2"
        >
          {retryLabel}
        </button>
      )}
    </div>
  </div>
);

export default ErrorState;
